import pytest
from subject import extract_topics, topic_error

@pytest.mark.unit
def test_extract_topics_returns_empty_for_unknown_suffix():
    source = "TOPIC_TEST = 'value'"
    assert extract_topics('file.txt', source) == []
    assert extract_topics('file.java', source) == []
    assert extract_topics('file', source) == []

@pytest.mark.unit
def test_extract_topics_py_simple_match():
    source = "TOPIC_NAME = 'value'"
    assert extract_topics('file.py', source) == [(1, 'value')]

@pytest.mark.unit
def test_extract_topics_py_multiple_matches():
    source = "TOPIC_A = 'a'\nTOPIC_B = 'b'"
    assert extract_topics('file.py', source) == [(1, 'a'), (2, 'b')]

